insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r28-v1','0.1.0','Green roofs, step 1: what kind of information?','reading','guided_practice','Do not read the article yet. For each question phrase, choose the kind of information it asks for, A-E.','Find the word in the question that names the kind of information (account, example, caution, justification, option, or a word with the same meaning) before you choose.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "mention of an option suited to buildings unable to carry a planted roof", "accepted_answers": ["E"], "taxonomy_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "A  an account"}, {"value": "B", "label": "B  an example"}, {"value": "C", "label": "C  a caution"}, {"value": "D", "label": "D  a justification"}, {"value": "E", "label": "E  an option"}]}, {"id": "q2", "prompt": "an account of how conditions after dark may weaken people''s capacity to cope with heat", "accepted_answers": ["A"], "taxonomy_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "A  an account"}, {"value": "B", "label": "B  an example"}, {"value": "C", "label": "C  a caution"}, {"value": "D", "label": "D  a justification"}, {"value": "E", "label": "E  an option"}]}, {"id": "q3", "prompt": "a warning that public money may be spent in the wrong places", "accepted_answers": ["C"], "taxonomy_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "A  an account"}, {"value": "B", "label": "B  an example"}, {"value": "C", "label": "C  a caution"}, {"value": "D", "label": "D  a justification"}, {"value": "E", "label": "E  an option"}]}, {"id": "q4", "prompt": "the reason councils give for charging owners of planted roofs lower fees", "accepted_answers": ["D"], "taxonomy_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "A  an account"}, {"value": "B", "label": "B  an example"}, {"value": "C", "label": "C  a caution"}, {"value": "D", "label": "D  a justification"}, {"value": "E", "label": "E  an option"}]}, {"id": "q5", "prompt": "an example of a way of coping with heat that makes the original problem worse", "accepted_answers": ["B"], "taxonomy_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "A  an account"}, {"value": "B", "label": "B  an example"}, {"value": "C", "label": "C  a caution"}, {"value": "D", "label": "D  a justification"}, {"value": "E", "label": "E  an option"}]}, {"id": "q6", "prompt": "a description of how plants carry heat away from a roof", "accepted_answers": ["A"], "taxonomy_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "A  an account"}, {"value": "B", "label": "B  an example"}, {"value": "C", "label": "C  a caution"}, {"value": "D", "label": "D  a justification"}, {"value": "E", "label": "E  an option"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 5, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "Step 1: do not read the article yet. Decide what KIND of information each question asks for.\n\nA  an account: how something happens, a cause leading to an effect\nB  an example: one real case of something more general\nC  a caution: a warning that something may be wrong or limited\nD  a justification: the reason someone gives for doing something\nE  an option: another choice or solution\n\nLook for the word in the question that tells you: account, description, example, caution, warning, justification, reason, option.", "teacher_notes": "1 E: ''option''.\n2 A: ''account of how''.\n3 C: ''warning'' = a caution.\n4 D: ''the reason councils give'' = a justification.\n5 B: ''example''.\n6 A: ''a description of how'' = an account (a process).\nTeach: circle the kind word first; a different word (warning, reason, description) can name the same kind.", "focus": "Select relevant information: identify the kind of information a matching-information question asks for before reading."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_06.json 0.1.0"}'::jsonb,'bda53c9a973f647536db6eb5d548bbaa357933268c08e2ed8b76016982d590fe',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r29-v1','0.1.0','Green roofs, step 2: does this paragraph contain it?','reading','guided_practice','Read only the paragraph named in each question. Choose YES if it contains the information, NO if it does not.','Both paragraphs in each pair share a topic. Choose YES only if the paragraph contains the right kind of information, not just the same topic or words.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Paragraph C: does it contain a caution against drawing wide conclusions from evidence collected at one location?", "accepted_answers": ["YES"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "options": [{"value": "YES", "label": "YES, it contains this"}, {"value": "NO", "label": "NO, it does not"}]}, {"id": "q2", "prompt": "Paragraph A: does it contain an account of how conditions after dark may weaken people''s capacity to cope with heat?", "accepted_answers": ["NO"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "options": [{"value": "YES", "label": "YES, it contains this"}, {"value": "NO", "label": "NO, it does not"}]}, {"id": "q3", "prompt": "Paragraph F: does it contain the justification some local authorities give for offering financial help?", "accepted_answers": ["NO"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "options": [{"value": "YES", "label": "YES, it contains this"}, {"value": "NO", "label": "NO, it does not"}]}, {"id": "q4", "prompt": "Paragraph F: does it contain an option suited to buildings unable to carry a planted roof?", "accepted_answers": ["YES"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "options": [{"value": "YES", "label": "YES, it contains this"}, {"value": "NO", "label": "NO, it does not"}]}, {"id": "q5", "prompt": "Paragraph B: does it contain an account of how conditions after dark may weaken people''s capacity to cope with heat?", "accepted_answers": ["YES"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "options": [{"value": "YES", "label": "YES, it contains this"}, {"value": "NO", "label": "NO, it does not"}]}, {"id": "q6", "prompt": "Paragraph D: does it contain an option suited to buildings unable to carry a planted roof?", "accepted_answers": ["NO"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "options": [{"value": "YES", "label": "YES, it contains this"}, {"value": "NO", "label": "NO, it does not"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 7, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "Cooling the city from the roof up\n\nA. On windless summer evenings, the core of a large metropolis may remain several degrees warmer than the surrounding countryside, a disparity known as the urban heat island effect. Asphalt, concrete and brick absorb solar radiation throughout the day and surrender it only gradually once the sun has set, while vehicles, air-conditioning units and industrial processes contribute heat of their own. Counter-intuitively, therefore, the contrast between town and country tends to peak not in the early afternoon, when sunlight is most intense, but several hours after dusk.\n\nB. The consequences extend well beyond discomfort. Epidemiologists studying successive heatwaves have linked prolonged night-time warmth to a marked rise in emergency hospital admissions, arguing that bodies deprived of the chance to cool down overnight are less able to withstand the following day''s heat; elderly residents of poorly ventilated top-floor apartments appear especially vulnerable. Electricity consumption climbs in parallel as air conditioners run for longer, and the waste heat these machines expel into the street intensifies the very problem they were bought to solve. For municipal authorities, lowering urban temperatures has consequently become as much a public health priority as an energy one.\n\nC. Among the responses that have gained traction is the green roof, in which a layer of growing medium and vegetation is laid over a waterproof membrane. Plants dissipate heat through evapotranspiration: moisture drawn up through the roots evaporates from the leaves, carrying energy away with it. The substrate beneath them also functions as insulation, retarding the passage of heat into the rooms below. Thermal imaging of individual buildings has repeatedly shown planted roofs to be dramatically cooler on hot afternoons than adjacent bitumen surfaces, although readings taken on a single rooftop reveal little about conditions in the surrounding district.\n\nD. The advantages, moreover, are unevenly distributed. Engineers note that a planted roof on a high-rise office block may keep its upper floors comfortable while doing almost nothing for the air at pavement level, where pedestrians actually experience the heat. Ecologists, for their part, caution that the thin mats of drought-tolerant sedum favoured by developers sustain only a fraction of the insect and bird life found in deeper, more varied plantings. Deeper substrate, however, is heavy when saturated, and a considerable proportion of older buildings could not bear the additional load without expensive structural reinforcement.\n\nE. Expense is the objection that property owners raise most persistently. Installation typically costs substantially more than a conventional replacement roof, and irrigation during dry spells, weeding and the inspection of drainage outlets impose recurring costs thereafter. Owners contend, with some justification, that while the wider public enjoys cooler streets, the financial burden falls entirely on them. A number of municipalities have responded with subsidies or reduced stormwater fees, reasoning that vegetated roofs retain rainfall that would otherwise overwhelm the sewers during heavy downpours.\n\nF. Urban planners increasingly regard green roofs as one element of a broader strategy rather than a remedy in themselves. Street trees cast shade precisely where people walk, and reflective ''cool roofs'', which bounce sunlight back rather than absorbing it, are far cheaper on buildings whose structure cannot support soil. Some planners also warn that grants concentrated on prestigious commercial developments risk cooling the districts that need it least. In their view, the question worth asking is not whether green roofs work in general but which combination of measures suits a particular neighbourhood''s buildings, budget and residents.", "teacher_notes": "1 YES: ''readings taken on a single rooftop reveal little about conditions in the surrounding district''.\n2 NO: A gives temperatures after dusk, nothing about people coping.\n3 NO: F criticises where grants go; it gives no reason for offering them.\n4 YES: cool roofs ''are far cheaper on buildings whose structure cannot support soil''.\n5 YES: ''bodies deprived of the chance to cool down overnight are less able to withstand the following day''s heat''.\n6 NO: D names buildings that cannot bear the load but offers no option.\nTeach: same topic is not enough; ask whether the paragraph has the kind of information.", "focus": "Locate specific detail: decide whether one paragraph contains a given kind of information."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_06.json 0.1.0"}'::jsonb,'0d05ffe9059d10f752b4742553dfd32409871be93f9069816a9fe5ea80300470',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r30-v1','0.1.0','Green roofs, step 3: two paragraphs, one trap','reading','guided_practice','Which paragraph contains the following information? Choose between the two paragraphs given. NB The same letter can be the answer more than once.','One paragraph in each pair shares a word or topic with the question. Choose the paragraph that has the meaning, and be ready to say why the other one is wrong.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "an account of how conditions after dark may weaken people''s capacity to cope with heat", "accepted_answers": ["B"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "Paragraph A"}, {"value": "B", "label": "Paragraph B"}]}, {"id": "q2", "prompt": "an example of a way of coping with heat that makes the original problem worse", "accepted_answers": ["B"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "Paragraph A"}, {"value": "B", "label": "Paragraph B"}]}, {"id": "q3", "prompt": "a caution against drawing wide conclusions from evidence collected at one location", "accepted_answers": ["C"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "C", "label": "Paragraph C"}, {"value": "D", "label": "Paragraph D"}]}, {"id": "q4", "prompt": "a reference to the justification some local authorities give for offering financial help", "accepted_answers": ["E"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "E", "label": "Paragraph E"}, {"value": "F", "label": "Paragraph F"}]}, {"id": "q5", "prompt": "mention of an option suited to buildings unable to carry a planted roof", "accepted_answers": ["F"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "D", "label": "Paragraph D"}, {"value": "F", "label": "Paragraph F"}]}, {"id": "q6", "prompt": "a description of how plants carry heat away from a roof", "accepted_answers": ["C"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "C", "label": "Paragraph C"}, {"value": "D", "label": "Paragraph D"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "Cooling the city from the roof up\n\nA. On windless summer evenings, the core of a large metropolis may remain several degrees warmer than the surrounding countryside, a disparity known as the urban heat island effect. Asphalt, concrete and brick absorb solar radiation throughout the day and surrender it only gradually once the sun has set, while vehicles, air-conditioning units and industrial processes contribute heat of their own. Counter-intuitively, therefore, the contrast between town and country tends to peak not in the early afternoon, when sunlight is most intense, but several hours after dusk.\n\nB. The consequences extend well beyond discomfort. Epidemiologists studying successive heatwaves have linked prolonged night-time warmth to a marked rise in emergency hospital admissions, arguing that bodies deprived of the chance to cool down overnight are less able to withstand the following day''s heat; elderly residents of poorly ventilated top-floor apartments appear especially vulnerable. Electricity consumption climbs in parallel as air conditioners run for longer, and the waste heat these machines expel into the street intensifies the very problem they were bought to solve. For municipal authorities, lowering urban temperatures has consequently become as much a public health priority as an energy one.\n\nC. Among the responses that have gained traction is the green roof, in which a layer of growing medium and vegetation is laid over a waterproof membrane. Plants dissipate heat through evapotranspiration: moisture drawn up through the roots evaporates from the leaves, carrying energy away with it. The substrate beneath them also functions as insulation, retarding the passage of heat into the rooms below. Thermal imaging of individual buildings has repeatedly shown planted roofs to be dramatically cooler on hot afternoons than adjacent bitumen surfaces, although readings taken on a single rooftop reveal little about conditions in the surrounding district.\n\nD. The advantages, moreover, are unevenly distributed. Engineers note that a planted roof on a high-rise office block may keep its upper floors comfortable while doing almost nothing for the air at pavement level, where pedestrians actually experience the heat. Ecologists, for their part, caution that the thin mats of drought-tolerant sedum favoured by developers sustain only a fraction of the insect and bird life found in deeper, more varied plantings. Deeper substrate, however, is heavy when saturated, and a considerable proportion of older buildings could not bear the additional load without expensive structural reinforcement.\n\nE. Expense is the objection that property owners raise most persistently. Installation typically costs substantially more than a conventional replacement roof, and irrigation during dry spells, weeding and the inspection of drainage outlets impose recurring costs thereafter. Owners contend, with some justification, that while the wider public enjoys cooler streets, the financial burden falls entirely on them. A number of municipalities have responded with subsidies or reduced stormwater fees, reasoning that vegetated roofs retain rainfall that would otherwise overwhelm the sewers during heavy downpours.\n\nF. Urban planners increasingly regard green roofs as one element of a broader strategy rather than a remedy in themselves. Street trees cast shade precisely where people walk, and reflective ''cool roofs'', which bounce sunlight back rather than absorbing it, are far cheaper on buildings whose structure cannot support soil. Some planners also warn that grants concentrated on prestigious commercial developments risk cooling the districts that need it least. In their view, the question worth asking is not whether green roofs work in general but which combination of measures suits a particular neighbourhood''s buildings, budget and residents.", "teacher_notes": "1 B: A mentions after dusk but only temperatures.\n2 B: ''intensifies the very problem they were bought to solve''; A lists air-conditioning only as a heat source.\n3 C: D limits the benefits but does not question the evidence.\n4 E: ''reasoning that vegetated roofs retain rainfall''; F criticises grants.\n5 F: cool roofs; D names the problem only.\n6 C: evapotranspiration; D mentions plants but discusses wildlife.\nTeach: a word you recognise is a warning, not an answer.", "focus": "Locate specific detail when a nearby paragraph shares the topic or key words (matching information)."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_06.json 0.1.0"}'::jsonb,'6b0ebab9824266c6dcc1c758ddfc60a0ab819a3adf19e05d1de96bd58eb22529',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r31-v1','0.1.0','Green roofs, step 4: predict, then find','reading','guided_practice','Complete each sentence. Write NO MORE THAN TWO WORDS from the passage for each answer. Copy the words exactly.','Before you read, decide what kind of word the gap needs (noun, plural noun, verb, time word). Then find it and check the nearby word that looks right but is not.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "During heatwaves, ________ rises as air conditioners run for longer.", "accepted_answers": ["electricity consumption"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q2", "prompt": "In a green roof, moisture ________ from the leaves and takes heat with it.", "accepted_answers": ["evaporates"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q3", "prompt": "Contrary to what might be expected, a city is warmest compared with the countryside not when the sun is strongest but well after ________.", "accepted_answers": ["dusk"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q4", "prompt": "Rooms directly under a green roof warm up less quickly because the growing layer provides ________.", "accepted_answers": ["insulation"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q5", "prompt": "On a very tall building, a planted roof may leave temperatures at ________ largely unchanged.", "accepted_answers": ["pavement level"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q6", "prompt": "Some councils charge owners of planted roofs lower ________ because these roofs hold back rainwater.", "accepted_answers": ["stormwater fees"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "Cooling the city from the roof up\n\nA. On windless summer evenings, the core of a large metropolis may remain several degrees warmer than the surrounding countryside, a disparity known as the urban heat island effect. Asphalt, concrete and brick absorb solar radiation throughout the day and surrender it only gradually once the sun has set, while vehicles, air-conditioning units and industrial processes contribute heat of their own. Counter-intuitively, therefore, the contrast between town and country tends to peak not in the early afternoon, when sunlight is most intense, but several hours after dusk.\n\nB. The consequences extend well beyond discomfort. Epidemiologists studying successive heatwaves have linked prolonged night-time warmth to a marked rise in emergency hospital admissions, arguing that bodies deprived of the chance to cool down overnight are less able to withstand the following day''s heat; elderly residents of poorly ventilated top-floor apartments appear especially vulnerable. Electricity consumption climbs in parallel as air conditioners run for longer, and the waste heat these machines expel into the street intensifies the very problem they were bought to solve. For municipal authorities, lowering urban temperatures has consequently become as much a public health priority as an energy one.\n\nC. Among the responses that have gained traction is the green roof, in which a layer of growing medium and vegetation is laid over a waterproof membrane. Plants dissipate heat through evapotranspiration: moisture drawn up through the roots evaporates from the leaves, carrying energy away with it. The substrate beneath them also functions as insulation, retarding the passage of heat into the rooms below. Thermal imaging of individual buildings has repeatedly shown planted roofs to be dramatically cooler on hot afternoons than adjacent bitumen surfaces, although readings taken on a single rooftop reveal little about conditions in the surrounding district.\n\nD. The advantages, moreover, are unevenly distributed. Engineers note that a planted roof on a high-rise office block may keep its upper floors comfortable while doing almost nothing for the air at pavement level, where pedestrians actually experience the heat. Ecologists, for their part, caution that the thin mats of drought-tolerant sedum favoured by developers sustain only a fraction of the insect and bird life found in deeper, more varied plantings. Deeper substrate, however, is heavy when saturated, and a considerable proportion of older buildings could not bear the additional load without expensive structural reinforcement.\n\nE. Expense is the objection that property owners raise most persistently. Installation typically costs substantially more than a conventional replacement roof, and irrigation during dry spells, weeding and the inspection of drainage outlets impose recurring costs thereafter. Owners contend, with some justification, that while the wider public enjoys cooler streets, the financial burden falls entirely on them. A number of municipalities have responded with subsidies or reduced stormwater fees, reasoning that vegetated roofs retain rainfall that would otherwise overwhelm the sewers during heavy downpours.\n\nF. Urban planners increasingly regard green roofs as one element of a broader strategy rather than a remedy in themselves. Street trees cast shade precisely where people walk, and reflective ''cool roofs'', which bounce sunlight back rather than absorbing it, are far cheaper on buildings whose structure cannot support soil. Some planners also warn that grants concentrated on prestigious commercial developments risk cooling the districts that need it least. In their view, the question worth asking is not whether green roofs work in general but which combination of measures suits a particular neighbourhood''s buildings, budget and residents.", "teacher_notes": "1 electricity consumption (B). Trap: ''waste heat'' is what the machines expel.\n2 evaporates (C). Trap: ''drawn up'' happens in the roots.\n3 dusk (A). Trap: ''early afternoon'' is the time ruled out.\n4 insulation (C). Trap: evapotranspiration cools the surface, not the rooms.\n5 pavement level (D). Trap: ''upper floors'' are what the roof does cool.\n6 stormwater fees (E). Traps: ''sewers'', ''drainage outlets'' are not charges.\nTeach: predict the word type, then look for contrast words (not ... but, while, rather than).", "focus": "Locate specific detail: complete sentences that paraphrase the passage, copying words exactly and rejecting nearby distractors."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_06.json 0.1.0"}'::jsonb,'76e7d005712f9eb0c3ffc2d2970544c8cbe9f51ec847b6ee23674d0aecfb83da',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r32-v1','0.1.0','Green roofs, step 5: who says what?','reading','guided_practice','Read the paragraph named in each question. Choose the correct letter, A, B, C or D.','Several groups are often named close together. Find who is saying, arguing or doing each thing (look for verbs such as note, caution, contend, argue, warn) before you choose.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Paragraph D: who chooses the thin mats of drought-tolerant sedum?", "accepted_answers": ["B"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  ecologists"}, {"value": "B", "label": "B  developers"}, {"value": "C", "label": "C  engineers"}, {"value": "D", "label": "D  property owners"}]}, {"id": "q2", "prompt": "Paragraph D: who criticises the thin mats of sedum?", "accepted_answers": ["C"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  developers"}, {"value": "B", "label": "B  engineers"}, {"value": "C", "label": "C  ecologists"}, {"value": "D", "label": "D  urban planners"}]}, {"id": "q3", "prompt": "Paragraph E: who says that they pay while the public gains?", "accepted_answers": ["D"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  municipalities"}, {"value": "B", "label": "B  the wider public"}, {"value": "C", "label": "C  urban planners"}, {"value": "D", "label": "D  property owners"}]}, {"id": "q4", "prompt": "Paragraph E: who responds by offering subsidies?", "accepted_answers": ["A"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  municipalities"}, {"value": "B", "label": "B  property owners"}, {"value": "C", "label": "C  epidemiologists"}, {"value": "D", "label": "D  developers"}]}, {"id": "q5", "prompt": "Paragraph D: which word shows that the engineers hold a view?", "accepted_answers": ["B"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  caution"}, {"value": "B", "label": "B  note"}, {"value": "C", "label": "C  contend"}, {"value": "D", "label": "D  warn"}]}, {"id": "q6", "prompt": "Paragraph B: who argues that warm nights make people less able to cope with heat?", "accepted_answers": ["D"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  municipal authorities"}, {"value": "B", "label": "B  elderly residents"}, {"value": "C", "label": "C  engineers"}, {"value": "D", "label": "D  epidemiologists"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "Cooling the city from the roof up\n\nA. On windless summer evenings, the core of a large metropolis may remain several degrees warmer than the surrounding countryside, a disparity known as the urban heat island effect. Asphalt, concrete and brick absorb solar radiation throughout the day and surrender it only gradually once the sun has set, while vehicles, air-conditioning units and industrial processes contribute heat of their own. Counter-intuitively, therefore, the contrast between town and country tends to peak not in the early afternoon, when sunlight is most intense, but several hours after dusk.\n\nB. The consequences extend well beyond discomfort. Epidemiologists studying successive heatwaves have linked prolonged night-time warmth to a marked rise in emergency hospital admissions, arguing that bodies deprived of the chance to cool down overnight are less able to withstand the following day''s heat; elderly residents of poorly ventilated top-floor apartments appear especially vulnerable. Electricity consumption climbs in parallel as air conditioners run for longer, and the waste heat these machines expel into the street intensifies the very problem they were bought to solve. For municipal authorities, lowering urban temperatures has consequently become as much a public health priority as an energy one.\n\nC. Among the responses that have gained traction is the green roof, in which a layer of growing medium and vegetation is laid over a waterproof membrane. Plants dissipate heat through evapotranspiration: moisture drawn up through the roots evaporates from the leaves, carrying energy away with it. The substrate beneath them also functions as insulation, retarding the passage of heat into the rooms below. Thermal imaging of individual buildings has repeatedly shown planted roofs to be dramatically cooler on hot afternoons than adjacent bitumen surfaces, although readings taken on a single rooftop reveal little about conditions in the surrounding district.\n\nD. The advantages, moreover, are unevenly distributed. Engineers note that a planted roof on a high-rise office block may keep its upper floors comfortable while doing almost nothing for the air at pavement level, where pedestrians actually experience the heat. Ecologists, for their part, caution that the thin mats of drought-tolerant sedum favoured by developers sustain only a fraction of the insect and bird life found in deeper, more varied plantings. Deeper substrate, however, is heavy when saturated, and a considerable proportion of older buildings could not bear the additional load without expensive structural reinforcement.\n\nE. Expense is the objection that property owners raise most persistently. Installation typically costs substantially more than a conventional replacement roof, and irrigation during dry spells, weeding and the inspection of drainage outlets impose recurring costs thereafter. Owners contend, with some justification, that while the wider public enjoys cooler streets, the financial burden falls entirely on them. A number of municipalities have responded with subsidies or reduced stormwater fees, reasoning that vegetated roofs retain rainfall that would otherwise overwhelm the sewers during heavy downpours.\n\nF. Urban planners increasingly regard green roofs as one element of a broader strategy rather than a remedy in themselves. Street trees cast shade precisely where people walk, and reflective ''cool roofs'', which bounce sunlight back rather than absorbing it, are far cheaper on buildings whose structure cannot support soil. Some planners also warn that grants concentrated on prestigious commercial developments risk cooling the districts that need it least. In their view, the question worth asking is not whether green roofs work in general but which combination of measures suits a particular neighbourhood''s buildings, budget and residents.", "teacher_notes": "1 B: sedum ''favoured by developers''. They choose it; they do not criticise it.\n2 C: ''Ecologists, for their part, caution''.\n3 D: ''Owners contend ... the financial burden falls entirely on them''.\n4 A: ''A number of municipalities have responded with subsidies''. They respond to the owners'' view; they do not hold it.\n5 B: ''Engineers note''.\n6 D: ''Epidemiologists ... arguing that bodies ...''. Elderly residents are the people at risk, not the speakers.\nTeach: circle every group name, then find its saying or doing verb.", "focus": "Identify viewpoint: match a view or action to the group that holds it when other groups are named nearby."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_06.json 0.1.0"}'::jsonb,'6146f795b26d85e786766cebb1d0c47c3f52ad2ab480b96660c86fedc765e2c7',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r33-v1','0.1.0','Green roofs: mixed trap check','reading','independent_check','Answer six new questions on the same passage. Questions 1-2: choose the paragraph, A-F. Questions 3-4: write NO MORE THAN TWO WORDS from the passage. Questions 5-6: choose the group, A-E. Work on your own, without notes, a dictionary or help. Tell your teacher if anything interrupted you.','Use the routine from Steps 1-5: name the kind of information, find it by meaning, copy words exactly, and check who holds each view.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Which paragraph contains a reference to a group that is especially at risk from heat?", "accepted_answers": ["B"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "Paragraph A"}, {"value": "B", "label": "Paragraph B"}, {"value": "C", "label": "Paragraph C"}, {"value": "D", "label": "Paragraph D"}, {"value": "E", "label": "Paragraph E"}, {"value": "F", "label": "Paragraph F"}]}, {"id": "q2", "prompt": "Which paragraph contains an explanation of why deeper planting is not always possible?", "accepted_answers": ["D"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "Paragraph A"}, {"value": "B", "label": "Paragraph B"}, {"value": "C", "label": "Paragraph C"}, {"value": "D", "label": "Paragraph D"}, {"value": "E", "label": "Paragraph E"}, {"value": "F", "label": "Paragraph F"}]}, {"id": "q3", "prompt": "Heat-absorbing materials such as asphalt release their stored energy only ________ after sunset.", "accepted_answers": ["gradually"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q4", "prompt": "Many older buildings could support deeper planting only after costly ________.", "accepted_answers": ["structural reinforcement"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q5", "prompt": "Which group says that planted roofs can protect the floors closest to them?", "accepted_answers": ["D"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  urban planners"}, {"value": "B", "label": "B  property owners"}, {"value": "C", "label": "C  ecologists"}, {"value": "D", "label": "D  engineers"}, {"value": "E", "label": "E  epidemiologists"}]}, {"id": "q6", "prompt": "Which group says that green roofs should not be treated as a complete answer on their own?", "accepted_answers": ["A"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  urban planners"}, {"value": "B", "label": "B  property owners"}, {"value": "C", "label": "C  ecologists"}, {"value": "D", "label": "D  engineers"}, {"value": "E", "label": "E  epidemiologists"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 10, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "Cooling the city from the roof up\n\nA. On windless summer evenings, the core of a large metropolis may remain several degrees warmer than the surrounding countryside, a disparity known as the urban heat island effect. Asphalt, concrete and brick absorb solar radiation throughout the day and surrender it only gradually once the sun has set, while vehicles, air-conditioning units and industrial processes contribute heat of their own. Counter-intuitively, therefore, the contrast between town and country tends to peak not in the early afternoon, when sunlight is most intense, but several hours after dusk.\n\nB. The consequences extend well beyond discomfort. Epidemiologists studying successive heatwaves have linked prolonged night-time warmth to a marked rise in emergency hospital admissions, arguing that bodies deprived of the chance to cool down overnight are less able to withstand the following day''s heat; elderly residents of poorly ventilated top-floor apartments appear especially vulnerable. Electricity consumption climbs in parallel as air conditioners run for longer, and the waste heat these machines expel into the street intensifies the very problem they were bought to solve. For municipal authorities, lowering urban temperatures has consequently become as much a public health priority as an energy one.\n\nC. Among the responses that have gained traction is the green roof, in which a layer of growing medium and vegetation is laid over a waterproof membrane. Plants dissipate heat through evapotranspiration: moisture drawn up through the roots evaporates from the leaves, carrying energy away with it. The substrate beneath them also functions as insulation, retarding the passage of heat into the rooms below. Thermal imaging of individual buildings has repeatedly shown planted roofs to be dramatically cooler on hot afternoons than adjacent bitumen surfaces, although readings taken on a single rooftop reveal little about conditions in the surrounding district.\n\nD. The advantages, moreover, are unevenly distributed. Engineers note that a planted roof on a high-rise office block may keep its upper floors comfortable while doing almost nothing for the air at pavement level, where pedestrians actually experience the heat. Ecologists, for their part, caution that the thin mats of drought-tolerant sedum favoured by developers sustain only a fraction of the insect and bird life found in deeper, more varied plantings. Deeper substrate, however, is heavy when saturated, and a considerable proportion of older buildings could not bear the additional load without expensive structural reinforcement.\n\nE. Expense is the objection that property owners raise most persistently. Installation typically costs substantially more than a conventional replacement roof, and irrigation during dry spells, weeding and the inspection of drainage outlets impose recurring costs thereafter. Owners contend, with some justification, that while the wider public enjoys cooler streets, the financial burden falls entirely on them. A number of municipalities have responded with subsidies or reduced stormwater fees, reasoning that vegetated roofs retain rainfall that would otherwise overwhelm the sewers during heavy downpours.\n\nF. Urban planners increasingly regard green roofs as one element of a broader strategy rather than a remedy in themselves. Street trees cast shade precisely where people walk, and reflective ''cool roofs'', which bounce sunlight back rather than absorbing it, are far cheaper on buildings whose structure cannot support soil. Some planners also warn that grants concentrated on prestigious commercial developments risk cooling the districts that need it least. In their view, the question worth asking is not whether green roofs work in general but which combination of measures suits a particular neighbourhood''s buildings, budget and residents.", "teacher_notes": "1 B: ''elderly residents of poorly ventilated top-floor apartments appear especially vulnerable''. Trap: D''s pedestrians feel the heat but are not said to be at risk.\n2 D: ''Deeper substrate ... is heavy when saturated ... could not bear the additional load''. Trap: F offers cool roofs, an option, not the reason.\n3 gradually (A). Trap: ''throughout the day'' is when the heat is absorbed.\n4 structural reinforcement (D). Trap: ''additional load'' is the problem, not the fix.\n5 D: engineers note the roof keeps ''its upper floors comfortable''.\n6 A: planners: ''one element of a broader strategy rather than a remedy in themselves''.\nFresh questions on a familiar passage: shows transfer of the routine, not new-text reading. Not a calibrated equivalent form.", "focus": "Matching information, sentence completion and matching features on one passage, with nearby distractors."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_06.json 0.1.0"}'::jsonb,'713ad5d6360e5918d511c690b9c8c38e7db2df41b4189cad18bf7ec7819ac8dd',true) on conflict (code) do nothing;
